type EVMInnerContext<'a, Host, KS, R> = Context<
    &'a BlockEnv,
    &'a TxEnv,
    CfgEnv,
    EtherlinkVMDB<'a, Host, KS, R>,
    Journal<'a, Host, KS, R>,
>;

type EvmContext<'a, Host, KS, R> = Evm<
    EVMInnerContext<'a, Host, KS, R>,
    (),
    EthInstructions<EthInterpreter, EVMInnerContext<'a, Host, KS, R>>,
    EtherlinkPrecompiles,
    EthFrame<EthInterpreter>,
>;

pub type EvmInspection<'a, Host, KS, INSP, R> = Evm<
    EVMInnerContext<'a, Host, KS, R>,
    INSP,
    EthInstructions<EthInterpreter, EVMInnerContext<'a, Host, KS, R>>,
    EtherlinkPrecompiles,
    EthFrame<EthInterpreter>,
>;

/// Controls commit behavior and optional balance injection in `run_transaction`.
pub enum TransactionOrigin {
    /// Original caller: commit EVM journal to durable storage, return withdrawals.
    UserInput { access_list: AccessList },
    /// Cross-runtime call: do NOT commit the journal.
    /// If `credit` is `Some`, inject a balance credit into the REVM journal
    /// before executing the transaction.
    ///
    /// Note: the credit lives behind an extra `journaled_state.checkpoint()`;
    /// the `CallTracer` keeps its own frame stack, so recorded traces are
    /// unaffected (`test_credit_checkpoint_keeps_call_tracer_depths`).
    CrossRuntime { credit: Option<(Address, U256)> },
    /// Read-only cross-runtime call: no balance credit, no journal
    /// commit, and the top-level frame runs with `is_static = true`
    /// (routed through [`EtherlinkHandler::new_static`]). REVM then
    /// enforces the standard `STATICCALL` contract — any
    /// state-mutating opcode halts with
    /// `StateChangeDuringStaticCall`, and only writes made *within*
    /// this call are unwound (outer-frame state in the same
    /// enclosing transaction is preserved).
    CrossRuntimeStatic,
}

#[derive(Debug, PartialEq)]
pub struct ExecutionOutcome {
    /// Result of the VM transaction execution.
    /// In particular contains gas used and emitted logs.
    pub result: ExecutionResult,
    /// Withdrawals generated by the transaction. This field will be empty if the
    /// transaction fails (or if the transaction doesn't produce any withdrawals).
    pub withdrawals: Vec<Withdrawal>,
}

pub struct GasData {
    gas_limit: u64,
    effective_gas_price: u128,
    maximum_gas_per_transaction: u64,
}

impl GasData {
    pub fn new(
        gas_limit: u64,
        effective_gas_price: u128,
        maximum_gas_per_transaction: u64,
    ) -> Self {
        Self {
            gas_limit,
            effective_gas_price,
            maximum_gas_per_transaction,
        }
    }
}

fn block_env(block_constants: &BlockConstants) -> Result<BlockEnv, EvmKernelError> {
    // TODO: Whenever the switch to REVM is completely made, readapt BlockConstants
    // structure to match alloy's type. The current structure is highly dependant
    // on what is needed for Sputnik.
    let basefee: u64 = block_constants
        .base_fee_per_gas()
        .try_into()
        .map_err(|_| EvmKernelError::BaseFeePerGasOverflow)?;
    Ok(BlockEnv {
        number: U256::from_le_slice(&u256_to_le_bytes(block_constants.number)),
        beneficiary: Address::from(block_constants.coinbase.0),
        timestamp: U256::from_le_slice(&u256_to_le_bytes(block_constants.timestamp)),
        gas_limit: block_constants.gas_limit,
        basefee,
        difficulty: U256::ZERO,
        prevrandao: Some(
            block_constants
                .prevrandao
                .map(|prevrandao| FixedBytes(prevrandao.0))
                .unwrap_or_default(),
        ),
        blob_excess_gas_and_price: Some(BlobExcessGasAndPrice::new(0, 1)),
        // The slot number of the block.
        // Incorporated as part of the Amsterdam upgrade via [EIP-7843].
        //
        // Not used for now, so we default to 0 here.
        slot_num: 0,
    })
}

#[instrument(skip_all)]
#[allow(clippy::too_many_arguments)]
fn tx_env(
    eth_accounts: &'_ mut impl KeySpace,
    journal: &mut TezosXJournal,
    caller: Address,
    destination: Option<Address>,
    gas_data: &GasData,
    value: U256,
    data: Bytes,
    authorization_list: Option<Vec<SignedAuthorization>>,
    chain_id: u64,
    origin: &mut TransactionOrigin,
) -> Result<TxEnv, EvmRunError> {
    let kind = match destination {
        Some(address) => TxKind::Call(address),
        None => TxKind::Create,
    };

    // Check journal first for uncommitted nonce changes from earlier
    // CrossRuntime transactions, then fall back to durable storage.
    let nonce = if let Some(account) = journal.evm.inner.state.get(&caller) {
        account.info.nonce
    } else {
        let storage_account =
            StorageAccount::from_address(&caller).map_err(EvmDbError::from)?;
        storage_account.info(eth_accounts)?.nonce
    };

    match origin {
        TransactionOrigin::UserInput { access_list } => {
            journal
                .evm
                .set_access_list(std::mem::take(access_list))
                .map_err(|_| EvmKernelError::AccessListAlreadySet)?;
        }
        TransactionOrigin::CrossRuntime { .. }
        | TransactionOrigin::CrossRuntimeStatic => (),
    };

    // Using the transaction environment builder helps to
    // derive the transaction type directly from the different
    // fields of the transaction.
    let tx_env_builder = TxEnvBuilder::new()
        .caller(caller)
        .gas_limit(gas_data.gas_limit)
        .gas_price(gas_data.effective_gas_price)
        .kind(kind)
        .value(value)
        .data(data)
        .nonce(nonce)
        .chain_id(Some(chain_id))
        .access_list(journal.evm.get_access_list_copy());

    let tx_env_builder = match authorization_list {
        Some(authorization_list) => {
            if authorization_list.is_empty() {
                return Err(EvmKernelError::EmptyAuthorizationList.into());
            }
            tx_env_builder.authorization_list_signed(authorization_list)
        }
        None => tx_env_builder,
    };

    let tx_env = tx_env_builder.build().map_err(EvmKernelError::from)?;

    Ok(tx_env)
}

/// EVM opcode for `ORIGIN` (0x32). Stable across all hardforks since
/// Frontier; named here so the override site reads as code, not magic.
const ORIGIN_OPCODE: u8 = 0x32;

/// Static gas cost of the `ORIGIN` opcode (2, the same `GAS_BASE` REVM
/// uses for the stock handler — see `revm-interpreter` `instructions::ORIGIN`).
const ORIGIN_STATIC_GAS: u64 = 2;

/// Custom `ORIGIN` opcode handler: when an inbound CRAC carries an
/// originator (`X-Tezos-Source`, exposed via
/// [`crate::journal::CrossRuntimeCall::cross_runtime_originator`]), push
/// that address as `tx.origin`; otherwise fall back to `TxEnv.caller`
/// (the standard EVM `ORIGIN` semantics).
///
/// This is how `tx.origin` carries the real outer-tx originator across
/// an `EVM <-> Michelson` boundary while `TxEnv.caller` keeps its usual
/// REVM meaning (the immediate caller's alias — so `msg.sender`, the
/// pre-execution nonce bump and the value deduction all stay on the
/// alias, exactly as they did before L2-1363). See L2-1441 for the
/// design rationale that replaces the earlier `TxEnv.caller`-overload
/// approach.
fn etherlink_origin<'a, Host, KS, R>(
    context: revm::interpreter::InstructionContext<
        '_,
        EVMInnerContext<'a, Host, KS, R>,
        EthInterpreter,
    >,
) where
    Host: KeyspaceHost<KS>,
    KS: SafeKeyspace,
    R: Registry<Journal = tezosx_journal::TezosXJournal>,
{
    use crate::journal::CrossRuntimeCall;
    use revm::interpreter::Host as InterpHost;
    let cross = context.host.journal().cross_runtime_originator();
    let value = match cross {
        Some(o) => o,
        None => InterpHost::caller(context.host),
    };
    if !context.interpreter.stack.push(value.into_word().into()) {
        context.interpreter.halt_overflow();
    }
}

/// Install [`etherlink_origin`] in `evm.instruction` as the handler for
/// `ORIGIN`. Call once per `Evm` construction (see
/// [`build_evm_inspector_context`] / [`build_evm_context`]). Uses
/// [`EvmInspection`] as the type alias for the etherlink-shaped `Evm`;
/// the non-inspector [`EvmContext`] is just `EvmInspection` with
/// `INSP = ()`, so the same function covers both call sites.
fn install_etherlink_origin<'a, Host, KS, R, INSP>(
    evm: &mut EvmInspection<'a, Host, KS, INSP, R>,
) where
    Host: KeyspaceHost<KS>,
    KS: SafeKeyspace,
    R: Registry<Journal = tezosx_journal::TezosXJournal>,
{
    evm.instruction.insert_instruction(
        ORIGIN_OPCODE,
        revm::interpreter::Instruction::new(
            etherlink_origin::<Host, KS, R>,
            ORIGIN_STATIC_GAS,
        ),
    );
}

/// EVM opcode for `GASPRICE` (0x3A). Stable across all hardforks since
/// Frontier; named here so the override site reads as code, not magic.
const GASPRICE_OPCODE: u8 = 0x3A;

/// Static gas cost of the `GASPRICE` opcode (2, `GAS_BASE` — the same
/// cost the stock `revm-interpreter` `instructions::gasprice` handler
/// charges).
const GASPRICE_STATIC_GAS: u64 = 2;

/// Custom `GASPRICE` opcode handler, installed only when servicing a
/// cross-runtime call. An inbound CRAC carries `gas_price = 0` on its
/// `TxEnv` (Michelson has no fee market and the originating runtime
/// settles payment at the topmost frame), so the stock opcode would
/// surface `0` to bytecode — diverging from the native EVM path. Push
/// the live block basefee instead: Etherlink ignores priority fees
/// (see `kernel::fees`), so the effective gas price of *every*
/// transaction — including the one that originated this CRAC — is
/// exactly `base_fee_per_gas`. Only the *observed* value is overridden:
/// `TxEnv.gas_price` stays `0`, so the caller debit and basefee burn
/// (role: accounting) are untouched. Mirrors the `ORIGIN` override,
/// which likewise reports a value distinct from what the `TxEnv` drives.
fn etherlink_gasprice<'a, Host, KS, R>(
    context: revm::interpreter::InstructionContext<
        '_,
        EVMInnerContext<'a, Host, KS, R>,
        EthInterpreter,
    >,
) where
    Host: KeyspaceHost<KS>,
    KS: SafeKeyspace,
    R: Registry<Journal = tezosx_journal::TezosXJournal>,
{
    use revm::interpreter::Host as InterpHost;
    let value = InterpHost::basefee(context.host);
    if !context.interpreter.stack.push(value) {
        context.interpreter.halt_overflow();
    }
}

/// Install [`etherlink_gasprice`] as the `GASPRICE` handler. Called from
/// the context builders only for cross-runtime origins, so a native EVM
/// transaction keeps the stock handler (reading the real
/// `TxEnv.gas_price`) and is left completely untouched.
fn install_etherlink_gasprice<'a, Host, KS, R, INSP>(
    evm: &mut EvmInspection<'a, Host, KS, INSP, R>,
) where
    Host: KeyspaceHost<KS>,
    KS: SafeKeyspace,
    R: Registry<Journal = tezosx_journal::TezosXJournal>,
{
    evm.instruction.insert_instruction(
        GASPRICE_OPCODE,
        revm::interpreter::Instruction::new(
            etherlink_gasprice::<Host, KS, R>,
            GASPRICE_STATIC_GAS,
        ),
    );
}

#[instrument(skip_all)]
#[allow(clippy::too_many_arguments)]
fn build_evm_inspector_context<'a, Host, KS, R>(
    db: EtherlinkVMDB<'a, Host, KS, R>,
    journal: &'a mut TezosXJournal,
    block: &'a BlockEnv,
    tx: &'a TxEnv,
    maximum_gas_per_transaction: u64,
    precompiles: EtherlinkPrecompiles,
    chain_id: u64,
    spec_id: SpecId,
    is_simulation: bool,
    is_cross_runtime: bool,
    alias_delegation: Option<Address>,
) -> Result<EvmInspection<'a, Host, KS, TracerInspector, R>, EvmRunError>
where
    Host: KeyspaceHost<KS>,
    KS: SafeKeyspace,
    R: Registry<Journal = tezosx_journal::TezosXJournal>,
{
    let mut cfg = CfgEnv::new()
        .with_chain_id(chain_id)
        .with_spec_and_mainnet_gas_params(spec_id);
    cfg.disable_eip3607 = is_simulation;
    cfg.tx_gas_limit_cap = Some(maximum_gas_per_transaction);
    // Cross-runtime calls carry `gas_price = 0` and now run against a
    // live block environment, so the EIP-1559 basefee preflight (which
    // validates a fee-paying user transaction) would reject every CRAC.
    // Disable it for cross-runtime origins; CRAC payment is settled at
    // the topmost frame. Native user transactions are unaffected. The
    // block-gas-limit check needs no such opt-out: a CRAC forwards at
    // most the caller's remaining gas (bounded by the per-transaction
    // cap), which the live block gas limit always exceeds.
    cfg.disable_base_fee = is_cross_runtime;

    // IMPORTANT
    // `Journal::new_with_inner` is the only working constructor of our `Journal` implementation.
    // `Journal` holds a mutable reference to its inner data that exists before it creation and must outlive it.
    // `Journal::new` exists only as a requirement for the `revm::context_interface::JournalTr` trait impl.
    // `Journal::new` is `unimplemented!()` and will panic.
    let mut journal = Journal::new_with_inner(db, journal);
    journal.set_spec_id(spec_id);
    let ctx = Context {
        tx,
        block,
        cfg,
        journaled_state: journal,
        chain: (),
        local: LocalContext::default(),
        error: Ok(()),
    };
    let mut evm = ctx
        .build_mainnet_with_inspector(TracerInspector)
        .with_precompiles(precompiles);
    install_etherlink_origin(&mut evm);
    if is_cross_runtime {
        install_etherlink_gasprice(&mut evm);
    }
    install_alias_delegation(&mut evm.ctx.journaled_state, alias_delegation)?;
    Ok(evm)
}

#[instrument(skip_all)]
#[allow(clippy::too_many_arguments)]
fn build_evm_context<'a, Host, KS, R: Registry<Journal = tezosx_journal::TezosXJournal>>(
    db: EtherlinkVMDB<'a, Host, KS, R>,
    journal: &'a mut TezosXJournal,
    block: &'a BlockEnv,
    tx: &'a TxEnv,
    maximum_gas_per_transaction: u64,
    precompiles: EtherlinkPrecompiles,
    chain_id: u64,
    spec_id: SpecId,
    is_simulation: bool,
    is_cross_runtime: bool,
    alias_delegation: Option<Address>,
) -> Result<EvmContext<'a, Host, KS, R>, EvmRunError>
where
    Host: KeyspaceHost<KS>,
    KS: SafeKeyspace,
{
    let mut cfg = CfgEnv::new()
        .with_chain_id(chain_id)
        .with_spec_and_mainnet_gas_params(spec_id);
    cfg.disable_eip3607 = is_simulation;
    cfg.tx_gas_limit_cap = Some(maximum_gas_per_transaction);
    // See `build_evm_inspector_context` for the rationale: open the
    // basefee preflight gate for cross-runtime origins, which run
    // `gas_price = 0` against a live block.
    cfg.disable_base_fee = is_cross_runtime;

    // IMPORTANT
    // `Journal::new_with_inner` is the only working constructor of our `Journal` implementation.
    // `Journal` holds a mutable reference to its inner data that exists before it creation and must outlive it.
    // `Journal::new` exists only as a requirement for the `revm::context_interface::JournalTr` trait impl.
    // `Journal::new` is `unimplemented!()` and will panic.
    let mut journal = Journal::new_with_inner(db, journal);
    journal.set_spec_id(spec_id);
    let ctx = Context {
        tx,
        block,
        cfg,
        journaled_state: journal,
        chain: (),
        local: LocalContext::default(),
        error: Ok(()),
    };
    let mut evm = ctx.build_mainnet().with_precompiles(precompiles);
    install_etherlink_origin(&mut evm);
    if is_cross_runtime {
        install_etherlink_gasprice(&mut evm);
    }
    install_alias_delegation(&mut evm.ctx.journaled_state, alias_delegation)?;
    Ok(evm)
}

/// Run the EVM transaction. Routes through [`EtherlinkHandler`]
/// (not REVM's stock `transact_one`) so the `first_frame_input`
/// override actually fires when `is_static_top_frame` is set, and so
/// the starting REVM call depth can be seeded from the cross-runtime
/// chain depth carried on `TezosXJournal`.
fn execute_transaction<
    'a,
    Host,
    KS: SafeKeyspace,
    R: Registry<Journal = tezosx_journal::TezosXJournal>,
>(
    evm_context: &mut EvmContext<'a, Host, KS, R>,
    tx: &'a TxEnv,
    transaction_hash: Option<[u8; TRANSACTION_HASH_SIZE]>,
    is_static_top_frame: bool,
    call_depth: usize,
) -> Result<ExecutionResult, EVMError<EvmDbError>>
where
    Host: KeyspaceHost<KS>,
{
    let opt_attrs_fun: Box<dyn FnOnce(&mut Host)> =
        if transaction_hash.is_some() && cfg!(feature = "tracing") {
            // The following unwrap is safe, see condition above.
            let hash = B256::from(transaction_hash.unwrap());
            let pretty_hash = format!("{hash}");
            let __attrs = [(
                "etherlink.transaction.hash".to_string(),
                OTelAttrValue::String(pretty_hash),
            )];
            Box::new(move |__host| {
                let _ = __host;
                __trace_kernel_add_attrs!(__attrs);
            })
        } else {
            Box::new(|__host| ())
        };
    __trace_kernel!("evm_context.transact_commit", {
        opt_attrs_fun(evm_context.db_mut().rk.host_mut());
        evm_context.set_tx(tx);
        let mut handler: EtherlinkHandler<_, EVMError<EvmDbError>, _> =
            if is_static_top_frame {
                EtherlinkHandler::new_static()
            } else {
                EtherlinkHandler::default()
            }
            .with_call_depth(call_depth);
        handler.run(evm_context)
    })
}

/// Install the alias delegation designator in the journaled state so the
/// alias-init sub-call resolves it. The write commits with the
/// transaction and reverts with the frame.
fn install_alias_delegation<
    Host: KeyspaceHost<KS>,
    KS: SafeKeyspace,
    R: Registry<Journal = tezosx_journal::TezosXJournal>,
>(
    journaled_state: &mut Journal<'_, Host, KS, R>,
    alias: Option<Address>,
) -> Result<(), EvmRunError> {
    if let Some(alias) = alias {
        journaled_state
            .load_account(alias)
            .map_err(EVMError::Database)?;
        journaled_state.set_code_with_hash(
            alias,
            alias_forwarder_delegation(),
            alias_forwarder_delegation_code_hash(),
        );
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
#[instrument(skip_all)]
pub fn run_transaction<
    'a,
    Host,
    KS: SafeKeyspace,
    R: Registry<Journal = tezosx_journal::TezosXJournal>,
>(
    rk: &'a mut RuntimeKeyspaces<Host, KS>,
    registry: &'a R,
    journal: &'a mut TezosXJournal,
    block_constants: &'a BlockConstants,
    transaction_hash: Option<[u8; TRANSACTION_HASH_SIZE]>,
    caller: Address,
    destination: Option<Address>,
    call_data: Bytes,
    gas_data: GasData,
    value: U256,
    authorization_list: Option<Vec<SignedAuthorization>>,
    is_simulation: bool,
    mut origin: TransactionOrigin,
) -> Result<ExecutionOutcome, EvmRunError>
where
    Host: KeyspaceHost<KS>,
{
    // Consume the pending alias delegation before any fallible step
    // so an early return cannot leave it dangling for the next
    // run transaction of the same operation.
    let alias_delegation = journal.evm.take_pending_alias_delegation();
    let block_env = block_env(block_constants)?;
    let is_cross_runtime = matches!(
        origin,
        TransactionOrigin::CrossRuntime { .. } | TransactionOrigin::CrossRuntimeStatic
    );
    let call_depth = journal
        .evm
        .revm_call_depth()
        .unwrap_or(if is_cross_runtime { 1 } else { 0 }) as usize;
    let tx = tx_env(
        rk.eth_accounts_mut(),
        journal,
        caller,
        destination,
        &gas_data,
        value,
        call_data,
        authorization_list,
        block_constants.chain_id.as_u64(),
        &mut origin,
    )?;

    // A user-input transaction was natively signed: have the commit
    // classify its caller as Native if still unclassified. The tag
    // rides the info write the nonce bump forces anyway, so this
    // costs no host call — unlike a pre-execution /origin check.
    let classify_native = (!is_cross_runtime).then_some(caller);
    let db = EtherlinkVMDB::new(rk, registry, block_constants, classify_native)?;

    if journal.evm.has_tracer() {
        let precompiles =
            EtherlinkPrecompiles::new(journal.evm.debug_precompiles_are_enabled());
        let mut evm_context = build_evm_inspector_context(
            db,
            journal,
            &block_env,
            &tx,
            gas_data.maximum_gas_per_transaction,
            precompiles,
            block_constants.chain_id.as_u64(),
            block_constants.spec_id,
            is_simulation,
            is_cross_runtime,
            alias_delegation,
        )?;

        let credit_checkpoint = match origin {
            TransactionOrigin::CrossRuntime {
                credit: Some((addr, amount)),
            } if amount > U256::ZERO => {
                let cp = evm_context.ctx.journaled_state.checkpoint();
                evm_context
                    .ctx
                    .journaled_state
                    .balance_incr(addr, amount)
                    .map_err(EVMError::Database)?;
                Some(cp)
            }
            _ => None,
        };

        // Use `EtherlinkHandler` so our `first_frame_input` override
        // fires; stock `inspect_one_tx` would bypass it.
        let is_static_top_frame = matches!(origin, TransactionOrigin::CrossRuntimeStatic);
        evm_context.set_tx(&tx);
        let mut handler: EtherlinkHandler<_, EVMError<EvmDbError>, _> =
            if is_static_top_frame {
                EtherlinkHandler::new_static()
            } else {
                EtherlinkHandler::default()
            }
            .with_call_depth(call_depth);
        let result = match handler.inspect_run(&mut evm_context) {
            Ok(r) => r,
            Err(e) => {
                if let Some(cp) = credit_checkpoint {
                    evm_context.ctx.journaled_state.checkpoint_revert(cp);
                }
                return Err(e.into());
            }
        };

        if let Some(err) = evm_context.ctx.journaled_state.take_deferred_error() {
            if let Some(cp) = credit_checkpoint {
                evm_context.ctx.journaled_state.checkpoint_revert(cp);
            }
            return Err(EvmKernelError::Runtime(err).into());
        }

        if let Some(cp) = credit_checkpoint {
            if result.is_success() {
                evm_context.ctx.journaled_state.checkpoint_commit();
            } else {
                evm_context.ctx.journaled_state.checkpoint_revert(cp);
            }
        }

        let withdrawals = if matches!(origin, TransactionOrigin::UserInput { .. }) {
            evm_context.commit_inner();
            evm_context.db_mut().take_withdrawals()
        } else {
            Vec::new()
        };

        Ok(ExecutionOutcome {
            result,
            withdrawals,
        })
    } else {
        let mut evm_context = build_evm_context(
            db,
            journal,
            &block_env,
            &tx,
            gas_data.maximum_gas_per_transaction,
            EtherlinkPrecompiles::new(journal.evm.debug_precompiles_are_enabled()),
            block_constants.chain_id.as_u64(),
            block_constants.spec_id,
            is_simulation,
            is_cross_runtime,
            alias_delegation,
        )?;

        let credit_checkpoint = match origin {
            TransactionOrigin::CrossRuntime {
                credit: Some((addr, amount)),
            } if amount > U256::ZERO => {
                let cp = evm_context.ctx.journaled_state.checkpoint();
                evm_context
                    .ctx
                    .journaled_state
                    .balance_incr(addr, amount)
                    .map_err(EVMError::Database)?;
                Some(cp)
            }
            _ => None,
        };

        let is_static_top_frame = matches!(origin, TransactionOrigin::CrossRuntimeStatic);
        let result = match execute_transaction(
            &mut evm_context,
            &tx,
            transaction_hash,
            is_static_top_frame,
            call_depth,
        ) {
            Ok(r) => r,
            Err(e) => {
                if let Some(cp) = credit_checkpoint {
                    evm_context.ctx.journaled_state.checkpoint_revert(cp);
                }
                return Err(e.into());
            }
        };

        if let Some(err) = evm_context.ctx.journaled_state.take_deferred_error() {
            if let Some(cp) = credit_checkpoint {
                evm_context.ctx.journaled_state.checkpoint_revert(cp);
            }
            return Err(EvmKernelError::Runtime(err).into());
        }

        if let Some(cp) = credit_checkpoint {
            if result.is_success() {
                evm_context.ctx.journaled_state.checkpoint_commit();
            } else {
                evm_context.ctx.journaled_state.checkpoint_revert(cp);
            }
        }

        let withdrawals = if matches!(origin, TransactionOrigin::UserInput { .. }) {
            evm_context.commit_inner();

            if !evm_context.db_mut().commit_status() {
                // No need to revert the possible database changes because
                // we are in a safe storage.
                return Err(EvmDbError::CommitMismatch.into());
            }

            evm_context.db_mut().take_withdrawals()
        } else {
            Vec::new()
        };

        Ok(ExecutionOutcome {
            result,
            withdrawals,
        })
    }
}

