    /// Branch 2: a legacy forwarder already has the delegation code but no
    /// Origin classification. ensure_alias stages the classification and
    /// commits it durably without re-running init.
    #[test]
    fn test_alias_forwarder_branch2_classification_persists_on_commit() {
        use crate::precompiles::constants::{
            alias_forwarder_delegation, alias_forwarder_delegation_code_hash,
        };

        let mut rk = RuntimeKeyspaces::default();
        init_precompile_bytecodes(rk.eth_accounts_mut(), true).unwrap();

        let native_address = "tz1Branch2Forwarder";
        let alias = {
            let hash = bytes_hash(native_address.as_bytes());
            Address::from_slice(&hash.0[0..20])
        };

        // Branch 2 precondition: delegation code present, classification empty.
        CodeStorage::add(
            rk.eth_accounts_mut(),
            alias_forwarder_delegation().original_byte_slice(),
            Some(alias_forwarder_delegation_code_hash()),
        )
        .unwrap();
        let mut alias_account = StorageAccount::from_address(&alias).unwrap();
        let mut info = alias_account.info(rk.eth_accounts_mut()).unwrap();
        info.code_hash = alias_forwarder_delegation_code_hash();
        alias_account
            .set_info_without_code(rk.eth_accounts_mut(), info)
            .unwrap();
        let precondition_origin =
            alias_account.info(rk.eth_accounts_mut()).unwrap().origin;
        assert_eq!(
            precondition_origin,
            AccountOrigin::Unclassified,
            "precondition: alias must have no classification yet"
        );

        let registry = Registry::new();
        let mut journal = TezosXJournal::mock(RuntimeId::Ethereum);
        registry
            .ensure_alias(
                &mut rk,
                &mut journal,
                AliasInfo {
                    runtime: tezosx_interfaces::RuntimeId::Tezos,
                    native_address: native_address.as_bytes().to_vec(),
                },
                None,
                tezosx_interfaces::RuntimeId::Ethereum,
                test_alias_creation_context(),
                tezosx_interfaces::Gas::new(1_000_000, RuntimeId::Ethereum),
            )
            .expect("Branch 2 ensure_alias should succeed");

        // The classification is staged, not yet durable.
        let staged_origin = StorageAccount::from_address(&alias)
            .unwrap()
            .info(rk.eth_accounts_mut())
            .unwrap()
            .origin;
        assert_eq!(
            staged_origin,
            AccountOrigin::Unclassified,
            "classification must be deferred until commit"
        );

        let block_constants = BlockConstants::test_block_with_no_fees();
        crate::journal::commit_evm_journal_from_external(
            &mut rk,
            &registry,
            &block_constants,
            &mut journal,
            None,
        )
        .expect("flush evm journal");

        // The info record carries the alias classification and its
        // payload even though the account itself was untouched by an
        // EVM run (leftover staged alias).
        let origin = StorageAccount::from_address(&alias)
            .unwrap()
            .info(rk.eth_accounts_mut())
            .unwrap()
            .origin;
        match origin {
            AccountOrigin::Alias(info) => assert_eq!(
                info.native_address,
                native_address.as_bytes().to_vec(),
                "classification must record the native address"
            ),
            other => {
                panic!("expected an Alias classification after commit, got {other:?}")
            }
        }
    }

    /// An unclassified EOA that 7702-delegated to the forwarder
    /// designator resolves to Native at commit through the has-code
    /// rule: real aliases are classified through their staged alias,
    /// never through code shape.
    #[test]
    fn test_commit_resolves_self_delegated_eoa_to_native() {
        use crate::database::EtherlinkVMDB;
        use crate::precompiles::constants::alias_forwarder_delegation_code_hash;
        use revm::primitives::AddressMap;
        use revm::state::{Account, AccountStatus};
        use revm::DatabaseCommit;

        let mut rk = RuntimeKeyspaces::default();
        let block = BlockConstants::test_block_with_no_fees();
        let registry = Registry::new();

        let eoa = Address::from_slice(&[0x78; 20]);
        let mut account = StorageAccount::from_address(&eoa).unwrap();
        let info = AccountInfo {
            balance: U256::from(1),
            nonce: 1,
            code_hash: alias_forwarder_delegation_code_hash(),
            origin: AccountOrigin::Unclassified,
            code: None,
        };
        account
            .set_info_without_code(rk.eth_accounts_mut(), info.clone())
            .unwrap();

        let mut db = EtherlinkVMDB::new(&mut rk, &registry, &block, None).unwrap();
        let mut touched = Account {
            info: info.into(),
            ..Account::default()
        };
        touched.status = AccountStatus::Touched;
        DatabaseCommit::commit(&mut db, AddressMap::from_iter([(eoa, touched)]));

        let origin = account.info(rk.eth_accounts_mut()).unwrap().origin;
        assert_eq!(
            origin,
            AccountOrigin::Native,
            "a self-delegated EOA without a staged alias is Native"
        );
    }

    /// Cross-frame atomicity: a successful Branch 3 materialization that is
    /// then discarded by an outer-frame revert must leave no durable alias,
    /// even when the enclosing operation goes on to commit other work.
    #[test]
    fn test_alias_materialization_dropped_on_outer_frame_revert() {
        use crate::precompiles::constants::alias_forwarder_delegation_code_hash;

        let mut rk = RuntimeKeyspaces::default();
        init_precompile_bytecodes(rk.eth_accounts_mut(), true).unwrap();

        let native_address = "tz1OuterRevertForwarder";
        let alias = {
            let hash = bytes_hash(native_address.as_bytes());
            Address::from_slice(&hash.0[0..20])
        };

        let registry = Registry::new();
        let mut journal = TezosXJournal::mock(RuntimeId::Ethereum);

        // Mirror the gateway-precompile frame checkpoint: the layered_state
        // overlay and the revm inner journal are checkpointed together.
        journal.evm.layered_state.checkpoint();
        let inner_cp = journal.evm.inner.checkpoint();

        // Branch 3: full materialization of a fresh alias.
        registry
            .ensure_alias(
                &mut rk,
                &mut journal,
                AliasInfo {
                    runtime: tezosx_interfaces::RuntimeId::Tezos,
                    native_address: native_address.as_bytes().to_vec(),
                },
                None,
                tezosx_interfaces::RuntimeId::Ethereum,
                test_alias_creation_context(),
                tezosx_interfaces::Gas::new(1_000_000, RuntimeId::Ethereum),
            )
            .expect("Branch 3 ensure_alias should succeed");

        // Staged in the overlay, nothing durable yet.
        assert!(journal
            .evm
            .layered_state
            .pending_alias_origin(&alias)
            .is_some());
        let staged_origin = StorageAccount::from_address(&alias)
            .unwrap()
            .info(rk.eth_accounts_mut())
            .unwrap()
            .origin;
        assert_eq!(staged_origin, AccountOrigin::Unclassified);

        // Outer frame reverts: unwind both layers, as checkpoint_revert does.
        journal.evm.layered_state.checkpoint_revert();
        journal.evm.inner.checkpoint_revert(inner_cp);
        assert!(
            journal
                .evm
                .layered_state
                .pending_alias_origin(&alias)
                .is_none(),
            "the staged alias must be dropped when its frame reverts"
        );

        // The enclosing operation still commits; the reverted alias must
        // contribute nothing durable.
        let block_constants = BlockConstants::test_block_with_no_fees();
        crate::journal::commit_evm_journal_from_external(
            &mut rk,
            &registry,
            &block_constants,
            &mut journal,
            None,
        )
        .expect("flush evm journal");

        let alias_account = StorageAccount::from_address(&alias).unwrap();
        assert_ne!(
            alias_account.info(rk.eth_accounts_mut()).unwrap().code_hash,
            alias_forwarder_delegation_code_hash(),
            "no delegation code_hash may survive an outer-frame revert"
        );
        let reverted_origin = alias_account.info(rk.eth_accounts_mut()).unwrap().origin;
        assert_eq!(
            reverted_origin,
            AccountOrigin::Unclassified,
            "no Origin classification may survive an outer-frame revert"
        );
    }

    /// Round-trip resolution must read a same-operation staged alias from the
    /// overlay before durable storage, and fall back to durable after the
    /// staging frame reverts.
    #[test]
    fn test_readonly_resolve_consults_staged_alias_overlay() {
        use crate::database::EtherlinkVMDB;
        use crate::journal::{CrossRuntimeCall, Journal};
        use tezosx_interfaces::{Origin, RuntimeId};

        let mut rk = RuntimeKeyspaces::default();
        let source = Address::from_slice(&[0xab; 20]);

        // Durable fallback classification: a distinct native address.
        StorageAccount::from_address(&source)
            .unwrap()
            .set_info_without_code(
                rk.eth_accounts_mut(),
                AccountInfo {
                    origin: AccountOrigin::Alias(AliasInfo {
                        runtime: RuntimeId::Tezos,
                        native_address: b"tz1durable".to_vec(),
                    }),
                    ..AccountInfo::default()
                },
            )
            .unwrap();

        let mut tj = TezosXJournal::mock(RuntimeId::Ethereum);
        tj.evm.layered_state.checkpoint();
        tj.evm.layered_state.create_alias(
            source,
            Origin::Alias(AliasInfo {
                runtime: RuntimeId::Tezos,
                native_address: b"tz1staged".to_vec(),
            }),
        );

        let registry = Registry::new();
        let block = BlockConstants::test_block_with_no_fees();

        // Overlay hit: resolves to the staged native, not the durable one.
        {
            let db = EtherlinkVMDB::new(&mut rk, &registry, &block, None).unwrap();
            let journal = Journal::new_with_inner(db, &mut tj);
            let target = journal
                .tezosx_resolve_source_alias_readonly(source, RuntimeId::Tezos, 1_000_000)
                .unwrap();
            assert_eq!(target, "tz1staged");
        }

        // Frame revert drops the staging; the same call falls back to durable.
        tj.evm.layered_state.checkpoint_revert();
        {
            let db = EtherlinkVMDB::new(&mut rk, &registry, &block, None).unwrap();
            let journal = Journal::new_with_inner(db, &mut tj);
            let target = journal
                .tezosx_resolve_source_alias_readonly(source, RuntimeId::Tezos, 1_000_000)
                .unwrap();
            assert_eq!(target, "tz1durable");
        }
    }

    /// Reproduction for the CREATE-frame checkpoint imbalance (MR !22056
    /// blocker). A CREATE frame opens via `create_account_checkpoint`,
    /// which — unlike `checkpoint` — does NOT push a Michelson
    /// `external_checkpoint` (nor a `layered_state` checkpoint), yet revm's
    /// `return_create` still closes the frame with `checkpoint_commit` /
    /// `checkpoint_revert`, both of which pop one. So a durable Michelson
    /// write performed inside a nested-and-committed CRAC sub-call is
    /// dropped from the snapshot stack at the sub-call's commit (it looks
    /// "outermost") and is therefore NOT restored when the enclosing CREATE
    /// frame reverts — exactly the alias-forwarder leak the Michelson-alias
    /// journaling work is meant to prevent.
    ///
    /// Sequence modeled — a top-level contract-creation tx whose constructor
    /// triggers an EVM->TEZ CRAC and then reverts:
    ///   CREATE open            (create_account_checkpoint — no external push)
    ///     gateway CALL open    (checkpoint — pushes external)
    ///       ensure_alias       (michelson snapshot of world state, write fwd)
    ///     gateway CALL commit  (checkpoint_commit — CRAC succeeds)
    ///   CREATE revert          (checkpoint_revert — constructor reverts)
    ///
    /// The forwarder write must be rolled back. This test asserts that and
    /// currently FAILS (the write survives), pinning the blocker. It will
    /// PASS once `create_account_checkpoint` also pushes the external /
    /// layered-state checkpoint so CREATE frames are balanced.
    #[test]
    fn create_frame_revert_drops_michelson_alias_snapshot() {
        use revm::context_interface::journaled_state::JournalTr;
        use revm::primitives::U256;
        use tezos_smart_rollup_host::path::OwnedPath;
        use tezos_smart_rollup_host::storage::StorageV1;

        let mut rk = RuntimeKeyspaces::default();
        let registry = Registry::new();
        let block_constants = BlockConstants::test_block_with_no_fees();

        // A durable Michelson path standing in for the alias forwarder
        // under /tez/tez_accounts. v0 = pre-forwarder state.
        let world =
            OwnedPath::try_from("/tez/tez_accounts/forwarder".to_string()).unwrap();
        rk.host_mut().store_write_all(&world, b"v0").unwrap();

        let mut tjournal = TezosXJournal::mock(RuntimeId::Ethereum);
        let db = crate::database::EtherlinkVMDB::new(
            &mut rk,
            &registry,
            &block_constants,
            None,
        )
        .unwrap();
        let mut journal = crate::journal::Journal::new_with_inner(db, &mut tjournal);

        // 1) Constructor (CREATE) frame opens. revm uses
        //    create_account_checkpoint for CREATE frames.
        let caller = Address::from_slice(&[0x11; 20]);
        let created = Address::from_slice(&[0x22; 20]);
        journal.load_account(caller).unwrap();
        journal.load_account(created).unwrap();
        let create_cp = journal
            .create_account_checkpoint(caller, created, U256::ZERO, DEFAULT_SPEC_ID)
            .expect("create_account_checkpoint");

        // 2) Constructor CALLs the gateway precompile: CALL frame opens.
        let _gateway_call_cp = journal.checkpoint();

        // 3) The gateway resolves an alias: ensure_alias snapshots the
        //    world state, then writes the forwarder (v1).
        journal
            .journal
            .michelson
            .checkpoint(journal.database.rk.host_mut(), &world)
            .expect("michelson world-state snapshot");
        journal
            .database
            .rk
            .host_mut()
            .store_write_all(&world, b"v1")
            .unwrap();

        // 4) The CRAC and the gateway CALL frame commit successfully.
        journal.checkpoint_commit();
        assert!(
            journal.take_deferred_error().is_none(),
            "commit_frame surfaced a deferred error"
        );

        // 5) The constructor reverts: the CREATE frame reverts.
        journal.checkpoint_revert(create_cp);
        assert!(
            journal.take_deferred_error().is_none(),
            "revert_frame surfaced a deferred error"
        );

        // The forwarder write MUST be rolled back with the reverted
        // constructor.
        let after = journal.database.rk.host().store_read_all(&world).unwrap();
        assert_eq!(
            after, b"v0",
            "BLOCKER: alias forwarder write survived the enclosing CREATE-frame \
             revert — create_account_checkpoint omits push_external_checkpoint, \
             so the nested CRAC commit prematurely drops the snapshot"
        );
    }

    // One mutez expressed in wei (10^12), mirroring the forwarder's own
    // `ONE_MUTEZ_IN_WEI` gate. Amounts below this are left resident instead
    // of being forwarded.
    const ONE_MUTEZ_WEI: u128 = 1_000_000_000_000;

    /// Compute the deterministic Ethereum alias address for `native_address`,
    /// mirroring `ensure_alias`'s `keccak256(native_address)[0..20]` scheme.
    fn alias_address_for(native_address: &str) -> Address {
        let hash = bytes_hash(native_address.as_bytes());
        Address::from_slice(&hash.0[0..20])
    }

    /// Directly set an account's EVM balance, simulating value that landed
    /// on the address (e.g. before the alias existed, or via a prior
    /// sub-mutez transfer) without going through a transaction.
    fn set_balance(eth_accounts: &mut impl KeySpace, address: Address, balance: U256) {
        let mut account = StorageAccount::from_address(&address).unwrap();
        let mut info = account.info(eth_accounts).unwrap();
        info.balance = balance;
        account.set_info_without_code(eth_accounts, info).unwrap();
    }

    /// Read an account's EVM balance.
    fn get_balance(eth_accounts: &mut impl KeySpace, address: Address) -> U256 {
        StorageAccount::from_address(&address)
            .unwrap()
            .info(eth_accounts)
            .unwrap()
            .balance
    }

    /// Read the mock Tezos balance recorded for `native_address`.
    fn tezos_balance(
        host: &mut impl StorageV1,
        registry: &Registry,
        native_address: &str,
    ) -> primitive_types::U256 {
        registry
            .get_balance(
                host,
                native_address.as_bytes(),
                tezosx_interfaces::RuntimeId::Tezos,
            )
            .unwrap_or(primitive_types::U256::zero())
    }

    /// Materialize the Ethereum alias for `native_address` and flush the EVM
    /// journal, mirroring what the kernel does on a successful parent
    /// operation: materialization is staged in the journal and only becomes
    /// durable at commit.
    fn materialize_alias(
        rk: &mut MockRuntimeKeyspaces,
        block_constants: &BlockConstants,
        native_address: &str,
    ) -> (Address, Registry, TezosXJournal) {
        let registry = Registry::new();
        let mut journal = TezosXJournal::mock(RuntimeId::Ethereum);
        let (alias_bytes, _) = registry
            .ensure_alias(
                rk,
                &mut journal,
                AliasInfo {
                    runtime: tezosx_interfaces::RuntimeId::Tezos,
                    native_address: native_address.as_bytes().to_vec(),
                },
                None,
                tezosx_interfaces::RuntimeId::Ethereum,
                test_alias_creation_context(),
                tezosx_interfaces::Gas::new(1_000_000, RuntimeId::Ethereum),
            )
            .expect("Failed to generate alias");
        let alias_hex = alias_bytes.strip_prefix("0x").unwrap_or(&alias_bytes);
        let alias = Address::from_slice(&hex::decode(alias_hex).unwrap());

        crate::journal::commit_evm_journal_from_external(
            rk,
            &registry,
            block_constants,
            &mut journal,
            None,
        )
        .expect("flush evm journal");

        (alias, registry, journal)
    }

    // The `AliasForwarder` events, declared inline since the contract has no
    // generated ABI binding in this crate. `nativeAddress` is indexed, so
    // the generated `Forwarded` type carries its topic hash rather than the
    // original string — irrelevant here, only `amount` is asserted.
    sol! {
        event Forwarded(string indexed nativeAddress, uint256 amount);
    }

    /// Whether `outcome` contains a `Forwarded` log.
    fn has_forwarded_event(outcome: &ExecutionOutcome) -> bool {
        outcome
            .result
            .logs()
            .iter()
            .any(|log| log.topics().first() == Some(&Forwarded::SIGNATURE_HASH))
    }

    /// Test that materializing an alias with a pre-existing balance writes
    /// only system state: no value moves, and the residue stays resident on
    /// the alias instead of being forwarded.
    #[test]
    fn test_alias_materialization_leaves_preexisting_balance_resident() {
        let mut rk = RuntimeKeyspaces::default();
        let mut block_constants = BlockConstants::test_block_with_no_fees();
        block_constants.tezos_experimental_features = true;

        // Initialize all precompiles (including AliasForwarder)
        init_precompile_bytecodes(rk.eth_accounts_mut(), true).unwrap();

        // Native Tezos address that should NOT receive the funds
        let native_address = "tz1PreexistingBal";
        let alias = alias_address_for(native_address);

        // Set pre-existing balance at the alias address BEFORE creating the alias
        let preexisting_balance = U256::from(5_000_000_000_000_000_000u128); // 5 ETH
        set_balance(rk.eth_accounts_mut(), alias, preexisting_balance);

        // Create the Ethereum alias
        let (created_alias, registry, _journal) =
            materialize_alias(&mut rk, &block_constants, native_address);
        assert_eq!(
            created_alias, alias,
            "Alias should be at the computed address"
        );

        // Materialization must not have triggered a gateway subcall: the
        // mock Tezos runtime never recorded an incoming CRAC.
        assert!(
            utilities::last_recorded_source(rk.host()).is_none(),
            "materialization must not forward any balance to the gateway"
        );

        // The native Tezos side never received anything.
        assert_eq!(
            tezos_balance(rk.host_mut(), &registry, native_address),
            primitive_types::U256::zero(),
            "materialization must not move value to the native address"
        );

        // The residue stays resident on the alias.
        assert_eq!(
            get_balance(rk.eth_accounts_mut(), alias),
            preexisting_balance,
            "the pre-existing balance must stay resident on the alias"
        );
    }

